function setPlate(w,study,rows,p,colors,d){
 const six=setColors(colors);
 if(study.variant==='flower'){flowerPanel(w,[10,32,570,548],'a',d,six);setSizePanel(w,[610,32,370,250],'b',d,six);setDegreePanel(w,[610,330,370,250],'c',d,six)}
 else if(study.variant==='upset'){upsetPanel(w,[10,32,640,548],'a',d,six,p.top);setSizePanel(w,[680,32,300,250],'b',d,six);setDegreePanel(w,[680,330,300,250],'c',d,six)}
 else{setSimilarityPanel(w,[10,32,555,548],'a',d,six);setNetworkPanel(w,[600,32,380,270],'b',d,six);const pairs=[];d.names.forEach((a,i)=>d.names.slice(i+1).forEach((b,k)=>pairs.push({name:a+' ∩ '+b,i,j:i+k+1,n:d.shared[i][i+k+1]})));pairs.sort((a,b)=>b.n-a.n||a.i-b.i||a.j-b.j);const shown=pairs.slice(0,6),a=area(w,[600,345,380,235],'c','Largest pairwise shared-item counts',[0,Math.max(...shown.map(v=>v.n),1)*1.2],[-.6,5.6],'Items · inclusive pair intersections','',{hideY:true,left:54});shown.forEach((v,i)=>{const y=5-i;w.add(text(a.x-7,a.sy(y)+3,v.name,{'font-size':8,'text-anchor':'end'}));w.add(N('rect',{x:a.x,y:a.sy(y)-7,width:a.sx(v.n)-a.x,height:14,rx:2,fill:six[i],'data-key':`pair:${v.i}:${v.j}`,'data-tip':`${v.name}\n${v.n} items (including higher-order overlaps)`}));w.add(text(a.sx(v.n)+5,a.sy(y)+3,v.n,{'font-size':7}))})}
 return[{label:'Distinct union items',value:d.union},{label:'Shared by all six',value:d.core},{label:'Exclusive to one set',value:d.unique.reduce((s,v)=>s+v,0)},{label:'Non-empty exact intersections',value:d.intersections.length}];
}

export function render(study,rows,p,colors,options={}){if(bioFamilies.includes(study.family))return renderBio({writer,title,area,text,N,path,line,dot},study,rows,p,colors,options);const w=writer(study.title,colors),d=options.simulation??simulate(study,rows,p);let metrics=[],note=options.custom?'User-provided numeric observations · pointwise normal-approximate intervals where shown':'Browser fixture · synthetic data · pointwise normal-approximate intervals where shown';switch(study.family){case'sets':metrics=setPlate(w,study,rows,p,colors,d);note=(options.custom?'User memberships':'Synthetic membership fixture')+' · exact counts from item identities · petals and network positions are schematic, not area-proportional';break;case'paired':metrics=study.variant==='agreement'?agreementPlate(w,study,rows,p,colors,d):pairedPlate(w,study,rows,p,colors,d);if(study.variant==='agreement')note+=' · limits: mean difference ±1.96 SD; descriptive, not confidence intervals';break;case'factorial':metrics=factorialPlate(w,study,rows,p,colors);break;case'performance':metrics=['budget','tails'].includes(study.variant)?performanceExpanded(w,study,rows,p,colors):performancePlate(w,study,rows,p,colors);break;case'retrieval':metrics=study.variant?retrievalExpanded(w,study,rows,p,colors,d):retrievalPlate(w,study,rows,p,colors,d);break;case'conflict':metrics=study.variant?conflictExpanded(w,study,rows,p,colors,d):conflictPlate(w,study,rows,p,colors,d);if(study.variant==='calibration')note+=' · target class: visual answer (0); ECE: 8 equal-width confidence bins';break;case'flow':metrics=flowPlate(w,study,rows,p,colors,d);break;case'representation':metrics=representationPlate(w,study,rows,p,colors);break;case'tasks':metrics=tasksPlate(w,study,rows,p,colors);note+=' · chords: baseline seed r ≥ .75; association, not causation';break;case'diffusion':metrics=study.variant?diffusionExpanded(w,study,rows,p,colors,d,options.extra??diffusionExtra(rows,p,d),options.phase??1):diffusionPlate(w,study,rows,p,colors,d,options.extra??diffusionExtra(rows,p,d),options.phase??1);note='Computed 2D analytic-score ODE · no trained image model · Euler / Heun / Midpoint · same-start numerical error'+(options.custom?' · user initial positions':'');break;}
return{svg:w.finish(note),metrics,simulation:d}}
